package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.util.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.nio.file.*;import java.sql.*;
@WebServlet("/document-download") public class DocumentDownloadServlet extends HttpServlet{protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){int id=Integer.parseInt(req.getParameter("id"));String path=null,name=null;try(PreparedStatement p=c.prepareStatement("SELECT doc.file_path,doc.file_name,s.department_id,s.user_id FROM documents doc JOIN staff s ON doc.staff_id=s.staff_id WHERE doc.document_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()){resp.sendError(404);return;}int dept=r.getInt(3);Integer owner=(Integer)r.getObject(4);if(Access.isStaff(u)&&(owner==null||owner!=u.id())||Access.isSupervisor(u)&&!Access.supervisorHasDepartment(c,u.id(),dept)){resp.sendError(403);return;}path=r.getString(1);name=r.getString(2);}}Path file=Path.of(getServletContext().getRealPath("/"),path);if(!Files.exists(file)){resp.sendError(404);return;}resp.setContentType(getServletContext().getMimeType(name)!=null?getServletContext().getMimeType(name):"application/octet-stream");resp.setHeader("Content-Disposition","attachment; filename=\""+name.replace("\"","")+"\"");Files.copy(file,resp.getOutputStream());}catch(Exception e){resp.sendError(400,e.getMessage());}}}
